def extract_name(content, filepath):
    m = re.search(r'^# (.+?)\s*做法', content, re.MULTILINE)
    if m:
        name = m.group(1)
        # Remove trailing '的' if present
        if name.endswith('的'):
            name = name[:-1]
        return name.strip()
    m = re.search(r'^# (.+?)(?:\.md)?$', content, re.MULTILINE)
    if m:
        return m.group(1).strip().replace('.md','')
    return os.path.basename(os.path.dirname(filepath))

def clean_amount(amount):
    """Clean up amount string."""
    # Remove trailing notes after * or newline
    amount = re.sub(r'\*.*$', '', amount).strip()
    # Remove parenthetical notes
    amount = re.sub(r'\(.*?\)', '', amount).strip()
    amount = re.sub(r'（.*?）', '', amount).strip()
    # Remove unit markers at end
    amount = re.sub(r'[^\d\d\.\-mlg]$', '', amount).strip()
    return amount

def parse_calc(content):
    """Parse 计算 section into list of (ingredient_name, amount)."""
    match = re.search(r'## 计算\n(.*?)(?=\n## |\Z)', content, re.DOTALL)
    if not match:
        return []
    block = match.group(1)
    results = []

    for line in block.split('\n'):
        orig = line
        # Strip list markers: - , * , + 
        line = line.strip()
        if not line:
            continue
        if not (line.startswith('- ') or line.startswith('* ') or line.startswith('+ ')):
            continue
        line = line[2:].strip()
        # Remove emoji prefixes
        line = re.sub(r'^[^\u4e00-\u9fff]+', '', line).strip()
        if not line:
            continue

        # Skip meta lines
        if re.match(r'^(每次|总量|每份|使用上述|此)', line):
            continue

        # Format: 名称 = 表达式
        m = re.match(r'^(.+?)\s*=\s*(.+)$', line)
        if m:
            raw_name = m.group(1).strip()
            raw_amt = m.group(2).strip()
            raw_amt = clean_amount(raw_amt)

            # Handle "茄子的数量 = 份数 * 1 个" -> name=茄子, amount=1 个
            name_m = re.match(r'^(.+?)的(数量|用量)?\s*$', raw_name)
            if name_m:
                name = name_m.group(1).strip()
            else:
                name = raw_name

            # Handle "肉量 = 份数 * 180 克" -> name=肉, amount=180 克
            amt_m = re.match(r'^(?:份数\s*\*\s*)?(.+)$', raw_amt)
            if amt_m:
                amount = amt_m.group(1).strip()
            else:
                amount = raw_amt
            amount = clean_amount(amount)

            if name and amount:
                results.append((name, amount))
            continue

        # Format: 名称用量为 表达式
        m = re.match(r'^(.+?)的用量为\s*(.+)$', line)
        if m:
            name = m.group(1).strip()
            amount = m.group(2).strip()
            amount = clean_amount(amount)
            if name and amount:
                results.append((name, amount))
            continue

        # Format: ingredient amount (space separated)
        m = re.match(r'^([\u4e00-\u9fff\w\-]+?)\s+(.+)$', line)
        if m:
            name = m.group(1).strip()
            amount = m.group(2).strip()
            amount = clean_amount(amount)
            if name and amount and amount[0].isdigit():
                results.append((name, amount))
                continue

        # Format: 鸡蛋（best）2个 - name with parenthetical note
        m = re.match(r'^([\u4e00-\u9fff\w\-]+?)（.+?）\s+(.+)$', line)
        if m:
            name = m.group(1).strip()
            amount = m.group(2).strip()
            amount = clean_amount(amount)
            if name and amount:
                results.append((name, amount))
                continue

    return results

def parse_tools_section(content):
    """Parse 必备原料和工具 section."""
    match = re.search(r'## 必备原料和工具\n(.*?)(?=\n## |\Z)', content, re.DOTALL)
    if not match:
        return []
    block = match.group(1)
    results = []
    for line in block.split('\n'):
